struct D : B, C { int d; };
// Layout D: [B::b][C::c][D::d][A::a] + vbptr(s) для доступа к виртуальной базе A

struct Empty {};
struct WithEmpty : Empty { int x; };
// sizeof(WithEmpty) == sizeof(int) — пустой базовый класс не занимает место
static_assert(sizeof(WithEmpty) == sizeof(int));

struct [[no_unique_address]] Empty {};
struct Holder {
    Empty e1;
    Empty e2;  // Могут иметь одинаковый адрес
    int x;
};
static_assert(sizeof(Holder) == sizeof(int));

