int x = 42;
float f = *reinterpret_cast<float*>(&x);  // UB! type punning через pointer cast

union { int i; float f; } u;
u.i = 42;
float f = u.f;  // UB до C++20! (active member = i)

// Через union — OK в C++20 (active member меняется неявно при чтении неактивного)
union { int i; float f; } u;
u.i = 0x3f800000;  // 1.0f в IEEE 754
float f = u.f;     // OK в C++20

// Лучше: std::bit_cast (C++20)
#include <bit>
float f = std::bit_cast<float>(0x3f800000);  // гарантированно безопасно, constexpr

#include <new>

struct A { int x; };
struct B { int y; };

void foo() {
    alignas(A) char storage[sizeof(A)];
    A* a = new (storage) A{42};
    a->x = 10;

    a->~A();
    B* b = new (storage) B{20};  // reuse memory

    // a всё ещё указывает на ту память, но объект A мёртв
    // Для доступа к новому объекту B через старый указатель:
    B* valid_b = std::launder(reinterpret_cast<B*>(a));
    // или просто используй b напрямую
}

