template <typename T, size_t PoolSize>
class ObjectPool {
    alignas(T) char storage[PoolSize * sizeof(T)];
    std::array<bool, PoolSize> used{};
    size_t next_free = 0;

public:
    template <typename... Args>
    T* allocate(Args&&... args) {
        for (size_t i = 0; i < PoolSize; ++i) {
            size_t idx = (next_free + i) % PoolSize;
            if (!used[idx]) {
                used[idx] = true;
                next_free = (idx + 1) % PoolSize;
                return std::construct_at(reinterpret_cast<T*>(storage + idx * sizeof(T)),
                                         std::forward<Args>(args)...);
            }
        }
        return nullptr;  // pool exhausted
    }

    void deallocate(T* ptr) {
        size_t idx = (reinterpret_cast<char*>(ptr) - storage) / sizeof(T);
        if (idx < PoolSize && used[idx]) {
            std::destroy_at(ptr);
            used[idx] = false;
        }
    }
};

struct S { int x; ~S() { std::cout << "dtor\n"; } };

void test() {
    S s;           // lifetime begins
    s.~S();        // lifetime ends
    s.x = 42;      // UB! access to dead object
    new (&s) S();  // new lifetime begins in same storage
    s.x = 99;      // OK, new object
}

