// Плохое выравнивание — много padding
struct Bad {
    char c;      // 1 byte
    // 7 bytes padding
    double d;    // 8 bytes
    int i;       // 4 bytes
    // 4 bytes padding
};  // sizeof = 24

// Хорошее — группируем по размеру
struct Good {
    double d;    // 8 bytes
    int i;       // 4 bytes
    char c;      // 1 byte
    // 3 bytes padding
};  // sizeof = 16

// Принудительное упакование (не рекомендуется для переносимости)
#pragma pack(push, 1)
struct Packed {
    char c;
    double d;
    int i;
};
#pragma pack(pop)

